// Hand-fix (handfixes.json apple-business-home-is-its-own): a relocated config dir is a
// customer's own, so an auth write under it leaves the default config as it was.
func TestAuthWriteUnderRelocatedHomeLeavesDefaultConfig(t *testing.T) {
	home, defaultConfigPath := resetCredentialEnv(t)
	if err := os.MkdirAll(filepath.Dir(defaultConfigPath), 0o700); err != nil {
		t.Fatalf("mkdir config: %v", err)
	}
	before := legacyConfigData(t, "https://settings.example", "legacy-secret")
	if err := os.WriteFile(defaultConfigPath, before, 0o600); err != nil {
		t.Fatalf("write legacy config: %v", err)
	}

	newConfigDir := filepath.Join(home, "new", "config")
	newDataDir := filepath.Join(home, "new", "data")
	t.Setenv("XDG_CONFIG_HOME", newConfigDir)
	t.Setenv("XDG_DATA_HOME", newDataDir)

	cfg, err := config.Load("")
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if got := cfg.AuthHeader(); strings.Contains(got, "legacy-secret") {
		t.Fatalf("a relocated run uses the default config's credential")
	}
	writeConfigCredential(t, cfg, "new-secret")

	after, err := os.ReadFile(defaultConfigPath)
	if err != nil {
		t.Fatalf("read default config: %v", err)
	}
	if string(after) != string(before) {
		t.Fatalf("the default config changed:\n%s", after)
	}
	activeConfigPath := filepath.Join(newConfigDir, "apple-business-cli", "config.toml")
	if data, err := os.ReadFile(activeConfigPath); err == nil && (strings.Contains(string(data), "new-secret") || strings.Contains(string(data), "settings.example")) {
		t.Fatalf("the relocated config holds the credential or the default config's settings:\n%s", data)
	}
	credsPath := filepath.Join(newDataDir, "apple-business-cli", "credentials.toml")
	if _, err := os.Stat(credsPath); err != nil {
		t.Fatalf("credentials file not found at relocated data dir: %v", err)
	}
}

